CREATE OR REPLACE FUNCTION public.can_manage_reporting(_uid uuid DEFAULT auth.uid()) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.admin_users WHERE user_id=_uid AND is_active=true AND role::text IN ('admin','super_admin','sales_manager','accounts','accounts_manager','accounts_payroll')); $$;
REVOKE ALL ON FUNCTION public.can_manage_reporting(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_manage_reporting(uuid) TO authenticated,service_role;
CREATE TABLE public.reporting_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, recipient_email text NOT NULL DEFAULT '', commission_pct numeric(7,4) NOT NULL DEFAULT 0, vat_pct numeric(7,4) NOT NULL DEFAULT 0, email_subject text NOT NULL DEFAULT 'Sales and commission report — {{period}}', email_body text NOT NULL DEFAULT 'Please find the sales report and head office invoice attached for {{period}}.', document_intro text NOT NULL DEFAULT 'Sales and head office commission summary', invoice_from text NOT NULL DEFAULT '', invoice_to text NOT NULL DEFAULT '', payment_details text NOT NULL DEFAULT '', sales_source text NOT NULL DEFAULT 'all', enabled boolean NOT NULL DEFAULT false, frequency text NOT NULL DEFAULT 'weekly', weekday integer NOT NULL DEFAULT 6, monthday integer NOT NULL DEFAULT 1, send_hour integer NOT NULL DEFAULT 9, next_send_at timestamptz, last_attempt_at timestamptz, last_error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.reporting_accounts TO authenticated; GRANT ALL ON public.reporting_accounts TO service_role;
ALTER TABLE public.reporting_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY reporting_accounts_access ON public.reporting_accounts FOR ALL TO authenticated USING(public.can_manage_reporting((SELECT auth.uid()))) WITH CHECK(public.can_manage_reporting((SELECT auth.uid())));
CREATE TABLE public.reporting_invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), account_id uuid NOT NULL REFERENCES public.reporting_accounts(id), invoice_number text NOT NULL UNIQUE, period_from date NOT NULL, period_to date NOT NULL, sales_total numeric(14,2) NOT NULL, sales_count integer NOT NULL, commission_pct numeric(7,4) NOT NULL, commission_amount numeric(14,2) NOT NULL, vat_pct numeric(7,4) NOT NULL, vat_amount numeric(14,2) NOT NULL, total numeric(14,2) NOT NULL, snapshot jsonb NOT NULL, scheduled_key text UNIQUE, email_status text NOT NULL DEFAULT 'not_sent', email_error text, sent_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reporting_invoices TO authenticated; GRANT ALL ON public.reporting_invoices TO service_role;
ALTER TABLE public.reporting_invoices ENABLE ROW LEVEL SECURITY;
CREATE POLICY reporting_invoice_read ON public.reporting_invoices FOR SELECT TO authenticated USING(public.can_manage_reporting((SELECT auth.uid())));
CREATE TABLE public.reporting_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid NOT NULL REFERENCES public.reporting_invoices(id), amount numeric(14,2) NOT NULL, paid_on date NOT NULL, reference text NOT NULL, recorded_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.reporting_payments TO authenticated; GRANT ALL ON public.reporting_payments TO service_role;
ALTER TABLE public.reporting_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY reporting_payment_read ON public.reporting_payments FOR SELECT TO authenticated USING(public.can_manage_reporting((SELECT auth.uid())));
CREATE OR REPLACE FUNCTION public.reporting_validate_account() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF length(trim(NEW.name)) NOT BETWEEN 1 AND 160 OR length(NEW.recipient_email)>254 OR length(NEW.email_subject)>500 OR length(NEW.email_body)>10000 OR length(NEW.document_intro)>10000 OR length(NEW.invoice_from)>3000 OR length(NEW.invoice_to)>3000 OR length(NEW.payment_details)>3000 THEN RAISE EXCEPTION 'Invalid reporting account fields'; END IF;
IF NEW.commission_pct<0 OR NEW.commission_pct>100 OR NEW.vat_pct<0 OR NEW.vat_pct>100 OR NEW.frequency NOT IN ('daily','weekly','monthly') OR NEW.weekday NOT BETWEEN 0 AND 6 OR NEW.monthday NOT BETWEEN 1 AND 28 OR NEW.send_hour NOT BETWEEN 0 AND 23 OR NEW.sales_source NOT IN ('all','website','agent') THEN RAISE EXCEPTION 'Invalid percentage or schedule'; END IF;
IF NEW.enabled AND (NEW.recipient_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(trim(NEW.invoice_from))=0 OR length(trim(NEW.invoice_to))=0 OR NEW.commission_pct<=0) THEN RAISE EXCEPTION 'Add a valid email, invoice sender/recipient and charge percentage before enabling'; END IF;
IF TG_OP='INSERT' OR ROW(NEW.enabled,NEW.frequency,NEW.weekday,NEW.monthday,NEW.send_hour) IS DISTINCT FROM ROW(OLD.enabled,OLD.frequency,OLD.weekday,OLD.monthday,OLD.send_hour) THEN NEW.next_send_at=NULL; END IF;
NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER reporting_validate_account BEFORE INSERT OR UPDATE ON public.reporting_accounts FOR EACH ROW EXECUTE FUNCTION public.reporting_validate_account();
CREATE OR REPLACE FUNCTION public.reporting_record_payment(_invoice uuid,_amount numeric,_paid_on date,_reference text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.reporting_invoices; paid numeric; result uuid; BEGIN
IF NOT public.can_manage_reporting(auth.uid()) THEN RAISE EXCEPTION 'Access denied'; END IF;
IF _amount IS NULL OR _amount<=0 OR _amount<>round(_amount,2) OR _paid_on IS NULL OR length(trim(_reference)) NOT BETWEEN 1 AND 250 THEN RAISE EXCEPTION 'Enter a positive payment, date and reference'; END IF;
SELECT * INTO inv FROM public.reporting_invoices WHERE id=_invoice FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Invoice not found'; END IF;
SELECT coalesce(sum(amount),0) INTO paid FROM public.reporting_payments WHERE invoice_id=_invoice;
IF _amount>inv.total-paid THEN RAISE EXCEPTION 'Payment exceeds outstanding balance'; END IF;
INSERT INTO public.reporting_payments(invoice_id,amount,paid_on,reference,recorded_by) VALUES(_invoice,_amount,_paid_on,trim(_reference),auth.uid()) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.reporting_record_payment(uuid,numeric,date,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reporting_record_payment(uuid,numeric,date,text) TO authenticated;
CREATE SEQUENCE public.reporting_invoice_number_seq;
GRANT USAGE ON SEQUENCE public.reporting_invoice_number_seq TO service_role;
CREATE OR REPLACE FUNCTION public.reporting_next_invoice_number() RETURNS text LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ SELECT 'HO-'||to_char(now(),'YYYY')||'-'||lpad(nextval('public.reporting_invoice_number_seq')::text,6,'0'); $$;
REVOKE ALL ON FUNCTION public.reporting_next_invoice_number() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.reporting_next_invoice_number() TO service_role;